pub struct Item {
    pub name: String,
    pub qty: u32,
}

#[derive(Default)]
pub struct Inventory {
    items: Vec<Item>,
    log: Vec<String>,
}

impl Inventory {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add(&mut self, name: &str, qty: u32) {
        self.items.push(Item { name: name.to_string(), qty });
        self.record(format!("added {name}"));
    }

    fn record(&mut self, msg: String) {
        self.log.push(msg);
    }

    /// Tops up every item below `threshold` by `amount` and logs each restock.
    pub fn restock_low(&mut self, threshold: u32, amount: u32) {
        for item in self.items.iter_mut() {
            if item.qty < threshold {
                item.qty += amount;
                self.record(format!("restocked {}", item.name));
            }
        }
    }

    pub fn qty(&self, name: &str) -> Option<u32> {
        self.items.iter().find(|i| i.name == name).map(|i| i.qty)
    }

    pub fn log(&self) -> &[String] {
        &self.log
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn restocks_only_low_items() {
        let mut inv = Inventory::new();
        inv.add("bolt", 2);
        inv.add("nut", 50);
        inv.restock_low(10, 20);
        assert_eq!(inv.qty("bolt"), Some(22));
        assert_eq!(inv.qty("nut"), Some(50));
        assert_eq!(inv.log().last().map(String::as_str), Some("restocked bolt"));
    }
}

use std::collections::HashMap;
use std::thread;

/// Counts words across all `chunks`, one worker thread per chunk.
pub fn count_words(chunks: Vec<String>) -> HashMap<String, usize> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    let mut handles = Vec::new();
    for chunk in chunks {
        handles.push(thread::spawn(|| {
            for word in chunk.split_whitespace() {
                *counts.entry(word.to_lowercase()).or_insert(0) += 1;
            }
        }));
    }
    for h in handles {
        h.join();
    }
    counts
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_across_chunks() {
        let counts = count_words(vec!["a b A".into(), "b c".into()]);
        assert_eq!(counts.get("a"), Some(&2));
        assert_eq!(counts.get("b"), Some(&2));
        assert_eq!(counts.get("c"), Some(&1));
    }
}

