use std::env;

#[derive(Debug)]
struct Config {
    listen_addr: String,
    workers: usize,
    log_level: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            listen_addr: "127.0.0.1:8080".to_string(),
            workers: 4,
            log_level: "info".to_string(),
        }
    }
}

fn main() {
    let config = Config::default();
    let verbose = env::args().any(|a| a == "-v");
    if verbose {
        println!("{config:?}");
    }
    println!("listening on {} with {} workers", config.listen_addr, config.workers);
}
